<?php declare(strict_types=1);require_once __DIR__.'/../includes/admin-auth.php';$tickets=load_json('support.json',[]);$error='';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$id=sanitize($_POST['id']??'');$action=sanitize($_POST['action']??'');if($id&&in_array($action,['open','closed'],true)){if(update_json('support.json',fn($items)=>array_map(fn($ticket)=>is_array($ticket)&&($ticket['id']??'')===$id?array_merge($ticket,['status'=>$action,'updated_at'=>date('c')]):$ticket,$items)))$message='Ticket updated.';else$error='The ticket could not be updated.';}elseif($id&&$action==='delete'&&delete_json_item('support.json',fn($ticket)=>is_array($ticket)&&($ticket['id']??'')===$id))$message='Ticket deleted.';else$error='The ticket action was invalid.';}?>
<main class="admin-shell"><aside class="admin-sidebar" data-admin-sidebar><div class="admin-brand"><a class="brand" href="<?= e(app_url('index.php')) ?>"><span class="brand-mark"><i></i><i></i></span><span>2B2X</span></a></div><nav class="admin-nav"><a href="<?= e(app_url('admin/index.php')) ?>">Dashboard</a><a href="<?= e(app_url('admin/users.php')) ?>">Users</a><a href="<?= e(app_url('admin/releases.php')) ?>">Releases</a><a href="<?= e(app_url('admin/downloads.php')) ?>">Downloads</a><a href="<?= e(app_url('admin/changelog.php')) ?>">Changelog</a><a href="<?= e(app_url('admin/blog.php')) ?>">Blog</a><a class="active" href="<?= e(app_url('admin/support.php')) ?>">Support</a><a href="<?= e(app_url('admin/settings.php')) ?>">Settings</a></nav><div class="admin-sidebar-footer"><a class="button button-ghost button-small" href="<?= e(app_url('admin/logout.php')) ?>">Logout</a></div></aside><div class="admin-main"><header class="admin-topbar"><button class="menu-toggle" data-admin-toggle aria-label="Open admin menu"><span></span><span></span></button><div><h1>Support center</h1><small style="color:var(--subtle)">Customer requests and ticket status</small></div><span class="status-pill"><?= count(array_filter($tickets,fn($t)=>is_array($t)&&($t['status']??'')==='open')) ?> open</span></header><div class="admin-content"><section class="admin-card admin-table-card"><div class="table-wrap"><table><thead><tr><th>Ticket</th><th>Customer</th><th>Subject</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php if(!$tickets):?><tr><td colspan=6><div class="empty-state"><h3>No support tickets</h3><p>Customer messages will appear here.</p></div></td></tr><?php else:foreach(array_reverse($tickets) as $ticket):?><tr><td><strong><?= e((string)$ticket['id']) ?></strong></td><td><?= e((string)$ticket['email']) ?></td><td><?= e(truncate((string)$ticket['subject'],40)) ?></td><td><span class="status-badge <?= ($ticket['status']??'open')==='open'?'status-badge--warning':'status-badge--success' ?>"><?= e((string)$ticket['status']) ?></span></td><td><?= e(format_date((string)$ticket['updated_at'])) ?></td><td><div class="admin-actions"><form method=post class="inline-form"><input type=hidden name=csrf_token value="<?= e(csrf_token()) ?>"><input type=hidden name=id value="<?= e((string)$ticket['id']) ?>"><input type=hidden name=action value="<?= ($ticket['status']??'open')==='open'?'closed':'open' ?>"><button type=submit><?= ($ticket['status']??'open')==='open'?'Close':'Reopen' ?></button></form><button type=button data-confirm="<?= e(app_url('admin/support.php?action=delete&id='.rawurlencode((string)$ticket['id']))) ?>">Delete</button></div></td></tr><?php endforeach;endif; ?></tbody></table></div></section><?php if($error):?><div class="alert error" style="margin-top:18px"><?= e($error) ?></div><?php elseif($message):?><div class="alert success" style="margin-top:18px"><?= e($message) ?></div><?php endif; ?></div></div><div class="modal" data-modal aria-hidden=true><div class="modal-card"><h2>Delete ticket?</h2><p>The request will be permanently removed.</p><form id=confirm-form method=post><input type=hidden name=csrf_token value="<?= e(csrf_token()) ?>"><input type=hidden name=action value=delete><input type=hidden name=id value=""><div class="modal-actions"><button class="button button-ghost" type=button data-close-modal>Cancel</button><button class="button button-primary" type=submit>Delete ticket</button></div></form></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
